<script setup>
import { ref, reactive, onMounted, onUnmounted } from 'vue'
import FilterSelect from './FilterSelect.vue'

const batchOpen = ref(false)
const batchRef = ref(null)
const autoRef = ref(null)
const autoOpen = ref(false)
const viewMode = ref('list')

const props = defineProps({
    filter: Object,
    selectedIds: Set,
    typeOptions: Array,
    groupOptions: Array
})

const enabledOptions = [     // 启用状态筛选的选项
    { label: '全部状态', value: '' },
    { label: '已启用', value: 'on' },
    { label: '已禁用', value: 'off' },
]

const autoOptions = reactive([
    {
        key: 'checkUpdate',
        label: '自动检查更新',
        desc: '定期检查 Mod 是否有新版本',
        value: false,
    },
    {
        key: 'autoDownload',
        label: '自动下载最新文件',
        desc: '检测到更新时，自动下载',
        value: false,
    },
    {
        key: 'autoSync',
        label: '自动同步数据',
        desc: '同步 Mod 信息和状态',
        value: true,
    },
    {
        key: 'autoAI',
        label: '自动 AI 分析',
        desc: '用 AI 分析 Mod 内容',
        value: false,
    },
])

const handleBatchOutside = (e) => {
    if (batchRef.value && !batchRef.value.contains(e.target)) {
        batchOpen.value = false
    }
}

const handleAutoOutside = (e) => {
    if (autoRef.value && !autoRef.value.contains(e.target)) {
        autoOpen.value = false
    }
}

const emit = defineEmits(['reset', 'action', 'install', 'uninstall', 'group', 'type', 'delete'])

onMounted(() => {
    document.addEventListener('click', handleBatchOutside)
    document.addEventListener('click', handleAutoOutside)
})

onUnmounted(() => {
    document.removeEventListener('click', handleBatchOutside)
    document.removeEventListener('click', handleAutoOutside)
})

</script>

